// TH14 v1.00b Extra 中Boss 第2组合，源 spellEx108
// 源: st07mbs.ecl.txt MBoss2 252-288 / MBoss2B 290-324（wrapper 入口）
//     MBossCard2 464-495 / MBossCard2B 497-513（符卡主体）
//     MBossCard2_at 539-561 / MBossCard2B_at 515-537（发射闭包）
//     MBossSuspend2 768-798（结束屏障，只到共享 GI0>=2 退出）
// 两实体同一组合生命周期：主侧源 I3=0、副侧 I3=10000；本卡直接建立两侧，
// 不再按 I3 重放上一段。GI0 用自由段 16 号槽共享。

const TIME_LIMIT: int = 2944;   // 120 开场 + 2820 窗口（2520 组合 + 300 尾）+ 4 启动余量
const OPENING_BUFFER: int = 120;
const SPELL_ID: int = 108;      // 源 spellEx(108, 2400, 500000, "弦楽「嵐のアンサンブル」")
const GI0_SLOT: int = 16;       // 源 $GI0 共享完成屏障

// 源 et 配置：etAim(0,1) 固定方向、etCount(0,1,1)、etSpeed(0,1.4,1.0)、etSprite(0,38/39,0)。
// etAngle 第二参（0.048706863）在 N=1 扇形的 F(1,0)=0，不产生角偏移。
const NOTE_SPEED: fx = 1.4fx;
const NOTE_BIRTH_RETREAT: fx = 5.6fx;      // 源 EX ANIM：position -= 4*velocity = 4*1.4
const NOTE_ACCEL_PER_FRAME: fx = 0.015fx;  // 源 EX ANGLE_ACCEL r=0.015
const NOTE_TURN_BAM: int = 121;            // 源 s=0.011635528 rad/帧 ≈ 121 BAM/帧
const NOTE_ANGLE_STEP: int = 40503;        // 源 3.883222 rad/发 ≈ 40503 BAM
const NOTE_ANGLE_RAND: int = 546;          // 源 RANDF2*0.05235988 rad ≈ ±546 BAM

// 源 etEx(0,0,2,1,...) + etEx(0,0,8,200,...)：出生 ANIM（表现省略，退位移保留）
// 与 ANGLE_ACCEL 200 帧（a=200、r=0.015、s=±0.011635528）。
// 目标 ANGLE_ACCEL 配方：set_accel + set_ang_vel，到期清两轴。
xformdef NOTE_ACCEL_TURN(dir: int) {
    set_accel(NOTE_ACCEL_PER_FRAME);
    @200 set_ang_vel((dir * NOTE_TURN_BAM) as angle);
    set_accel(0fx);
    set_ang_vel(0deg);
}

// 源 MBossCard2_at / MBossCard2B_at：%A=%RANDRAD，$B=50000；
// 每轮 etAngle(%A) → etOn → wait(2)，etOn 只发一颗（1x1）。
// 窗口按各侧源超时截断：主侧卡内 90→2400 共 1155 发，副侧 90→2280 共 1095 发。
async sub note_fire(shape: int, dir: int, shots: int) {
    var a: angle = (rand(65536)) as angle;   // %RANDRAD：全圆均匀，每任务一次
    var off: int = 0;
    for k in 0..shots {
        // etOn：弹在敌位置出生，ANIM 退位移沿出生角向后 4v
        _ = fire(shape, 0,
                 $self_x - NOTE_BIRTH_RETREAT * cos(a),
                 $self_y - NOTE_BIRTH_RETREAT * sin(a),
                 NOTE_SPEED, a, NOTE_ACCEL_TURN(dir), none);
        // 源 %A = %A ∓ (3.883222 + RANDF2*0.05235988)，每发一次（主侧减、副侧加）
        off = (rand(65536) - 32768) * NOTE_ANGLE_RAND / 32768;
        a = a + ((dir * (NOTE_ANGLE_STEP + off)) as angle);
        wait(2);
    }
}

// 源 MBossSuspend2 768-798：GI0++，movePosTime(120,1,0,-64)，等 GI0>=2。
// 屏障到达后源调用 @MBoss3/MBoss3B；本卡边界不执行后继攻击。
sub suspend_and_barrier() {
    set_global(GI0_SLOT, global(GI0_SLOT) + 1);
    move_to(120, 0fx, -64fx, EASE_QUAD_IN);
    while global(GI0_SLOT) < 2 {
        wait(1);
    }
}

// 源 MBoss2 252-288 + MBossCard2 464-495
async sub main_boss() {
    set_hitbox(24fx);   // 源 setHitbox(48,48)：普通圆取宽×0.5
    set_hurtbox(24fx);  // 源 setHurtbox(48,48)
    set_invuln(65535);  // 无敌训练外壳；源 setInvuln(120) 由外壳覆盖
    // 源 wrapper 的 etClear/laserCancel/killAllAsync/enmKillAll 清的是上一段残留，
    // 独立场景无旧敌/弹，不导入。flagClear(19) 开启体碰即目标默认状态。
    move_to(60, -32fx, 128fx, EASE_QUAD_OUT);   // movePosTime(60,4,-32,128)
    wait(120);                                  // 源 wait(120)，60 帧移动已在此内完成
    // 源 MBossCard2:466 timerReset 把本侧时限基点到此刻（2400 帧）
    wait(60);                                   // 源 wait(60) + EffChargePoint3（表现省略）
    wait(30);                                   // 源 +90 时间标签
    spawn note_fire(TH14_NOTE_RED, -1, 1155);   // 源 @MBossCard2_at() async
    wait(2310);                                 // 卡内 90 → 2400（本侧 timerReset 基点）
    suspend_and_barrier();
}

// 源 MBoss2B 290-324 + MBossCard2B 497-513
async sub sub_boss() {
    set_hitbox(24fx);
    set_hurtbox(24fx);
    set_invuln(65535);
    move_to(60, 32fx, 128fx, EASE_QUAD_OUT);    // movePosTime(60,4,32,128)
    wait(120);
    // 副侧沿 wrapper:300 的 timerReset 起算，卡入口已用掉 120 帧，本段无二次 reset
    wait(60);
    wait(30);
    spawn note_fire(TH14_NOTE_BLUE, 1, 1095);   // 源 @MBossCard2B_at() async
    wait(2190);                                 // 卡内 90 → 2280（= wrapper 后 2400）
    suspend_and_barrier();
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, -64fx, 2400, 0, 0, 0, main_boss);  // 源 lifeSet(2400)
    _ = spawn_enemy(0fx, -64fx, 2400, 0, 0, 0, sub_boss);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_global(GI0_SLOT, 0);   // 源 MBossCard2:482 $GI0 = 0
    spell_begin(0, SPELL_ID, pattern, TIME_LIMIT, 500000, 0, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}

